if __name__ == "__main__":
    root = Path(__file__).parent / "data" / "documents"
    n = 0
    for cat, items in DOCS.items():
        d = root / cat
        d.mkdir(parents=True, exist_ok=True)
        for i, (title, body) in enumerate(items, 1):
            (d / f"{cat}_{i:02d}.txt").write_text(f"{title}\n\n{body}\n", encoding="utf-8")
            n += 1
    print(f"Created {n} documents in {root}")
